SELECT * FROM base_vendor
AND vendor_type = #{vendorType}
AND use_yn = #{useYn}
AND (vendor_name LIKE CONCAT('%', #{keyword}, '%') OR vendor_code LIKE CONCAT('%', #{keyword}, '%') OR REPLACE(biz_no, '-', '') LIKE CONCAT('%', REPLACE(#{keyword}, '-', ''), '%'))
ORDER BY vendor_code ASC

SELECT * FROM base_vendor
WHERE biz_no = #{bizNo}

    AND vendor_id != #{excludeId}

LIMIT 1

